(()=>{
let showMapGuide=true;
const storageKey='hypercubic-map-structure-v1';
const categories=[['Batch processing',271,170],['Business logic changes',935,120],['Performance optimization',1376,95],['Data & interfaces',1388,390],['Modernization & refactoring',1354,613],['Regression testing',1071,676],['Team handover',128,665],['Testing & validation',210,404]];
const cases=[['Fix a duplicate refund after restart',609,232,'refund'],['Resolve an S0C7 in payment processing',401,308,'s0c7'],['Investigate a missing settlement record',798,336,'missing'],['Fix an incorrect month-end fee',771,548,'fee'],['Resolve a customer record update failure',543,635,'update']];
const initial=[{id:'root',label:'Debugging & incidents',x:588,y:424,parent:null,kind:'root'},...categories.map(([label,x,y],i)=>({id:'category-'+i,label,x,y,parent:'root',kind:'category'})),...cases.map(([label,x,y,ticket])=>({id:'case-'+ticket,label,x,y,parent:'root',kind:'case',ticket}))];
let nodes=structuredClone(initial);
try{const stored=JSON.parse(localStorage.getItem(storageKey));if(Array.isArray(stored)&&stored.every(n=>typeof n.id==='string'&&typeof n.label==='string'&&Number.isFinite(n.x)&&Number.isFinite(n.y)))nodes=stored}catch{}
const fm={expanded:new Set(),edit:false,fit:false,zoom:1,x:0,y:0,query:'',dialog:null,undo:null};
const baseKnowledge=knowledge,baseBind=bindKnowledge;
const shell=()=>'<header class="mac-titlebar"><div class="mac-traffic"><button class="mac-close" data-action="kb-desktop" aria-label="Close Knowledge Capture"><span>×</span></button><button class="mac-minimize" data-action="kb-desktop" aria-label="Minimize Knowledge Capture"><span>−</span></button><button class="mac-maximize" data-action="kb-maximize" aria-label="Toggle full screen"><span>↗</span></button></div><strong>Knowledge Capture</strong></header>';
function save(next){try{localStorage.setItem(storageKey,JSON.stringify(next));nodes=next;return true}catch{toast('Could not save the map. Free browser storage and try again.');return false}}
function visible(node,seen=new Set()){if(fm.edit||fm.query||!node.parent||node.kind==='category')return true;if(seen.has(node.id))return false;seen.add(node.id);const parent=nodes.find(n=>n.id===node.parent);return !!parent&&fm.expanded.has(parent.id)&&visible(parent,seen)}
function matches(node){const ticket=window.demoTickets?.[node.ticket];return !fm.query||[node.label,ticket?.id,ticket?.project].join(' ').toLowerCase().includes(fm.query.toLowerCase())}
function controls(node){return `<div class="map-node-tools" role="group" aria-label="Edit ${esc(node.label)}"><button data-map="add" data-id="${esc(node.id)}" aria-label="Add note to ${esc(node.label)}" data-tooltip="Add note">+</button><button data-map="rename" data-id="${esc(node.id)}" aria-label="Rename ${esc(node.label)}" data-tooltip="Rename">${icon('edit')}</button><button data-map="delete" data-id="${esc(node.id)}" aria-label="Delete ${esc(node.label)}" data-tooltip="Delete node">${icon('trash')}</button></div>`}
function canvas(){const shown=nodes.filter(n=>visible(n));return `<div class="rf-stage"><div class="rf-art"><svg class="rf-lines map-edges" width="1659" height="855" viewBox="0 0 1659 855" aria-hidden="true">${shown.map(n=>{const p=shown.find(p=>p.id===n.parent);return p?`<line x1="${p.x}" y1="${p.y}" x2="${n.x}" y2="${n.y}"/>`:''}).join('')}</svg>${shown.map(n=>{const hasChildren=nodes.some(child=>child.parent===n.id);const task=n.kind==='case'&&n.ticket;return `<div class="map-node ${n.kind==='root'?'map-root':''} ${task?'map-task':''} ${fm.query&&!matches(n)?'map-muted':''}" style="left:${n.x}px;top:${n.y}px"><button class="map-node-main" ${!fm.edit&&task?`data-nb="refine-case:${esc(n.ticket)}"`:`data-map="toggle" data-id="${esc(n.id)}"`} aria-label="${esc(n.label)}${task&&!fm.edit?' · View knowledge details':''}" ${hasChildren&&!task&&!fm.edit?`aria-expanded="${fm.expanded.has(n.id)}"`:''}><span>${esc(n.label)}</span>${!fm.edit?task?'<small class="map-enter">View details <b aria-hidden="true">→</b></small>':hasChildren?`<small>${fm.expanded.has(n.id)?'−':'+'}</small>`:'':''}</button>${fm.edit?controls(n):task&&hasChildren?`<button class="map-notes" data-map="toggle" data-id="${esc(n.id)}" aria-label="${fm.expanded.has(n.id)?'Hide':'Show'} notes of ${esc(n.label)}" aria-expanded="${fm.expanded.has(n.id)}">${fm.expanded.has(n.id)?'− Hide notes':'+ Notes'}</button>`:''}</div>`}).join('')}${!nodes.length?'<div class="map-empty"><p>No folders yet</p><button class="button" data-map="add">Add note</button></div>':''}</div></div>`}
function dialog(){if(!fm.dialog)return '';const d=fm.dialog;const node=nodes.find(n=>n.id===d.id);return `<div class="map-dialog-backdrop"><section class="map-dialog" role="dialog" aria-modal="true" aria-labelledby="map-dialog-title"><h2 id="map-dialog-title">${d.action==='rename'?'Rename node':'Add note'}</h2><form id="map-node-form"><label for="map-node-name">Name</label><input id="map-node-name" name="label" maxlength="80" required value="${d.action==='rename'?esc(node?.label||''):''}" autocomplete="off"><footer><button type="button" class="button" data-map="cancel">Cancel</button><button class="button primary">${d.action==='rename'?'Save name':'Add note'}</button></footer></form></section></div>`}
knowledge=function(){if(kb.view!=='map'){showMapGuide=true;return baseKnowledge();}document.title='Knowledge Capture · My Map';return `<div class="wallpaper"></div><main class="knowledge-app rf-app ${kb.maximized?'maximized':''}">${shell()}${workspaceRail('map')}<section class="rf-map ${fm.edit?'map-editing':''}" aria-label="My Map"><header class="map-toolbar"><div><h1>My Map</h1><p>${fm.edit?'Hover or focus a node to add, rename, or delete.':'Pinch to zoom. Drag to explore. Choose Edit to add or change notes.'}</p></div><div><button class="button ${fm.edit?'primary':''}" data-map="edit" aria-pressed="${fm.edit}">${fm.edit?'Done Editing':'Edit'}</button><button class="button primary" data-map="upload">Upload to Library <span aria-hidden="true">↗</span></button></div></header>${showMapGuide?`<aside class="map-guide-inline" aria-label="Map tips"><span>Pinch to zoom in or out. Choose <strong>Edit</strong> to organize your notes.</span><button data-map="guide-close" aria-label="Dismiss map tips">×</button></aside>`:''}${canvas()}${fm.undo?'<div class="map-undo" role="status">Node deleted · Notes kept <button data-map="undo">Undo</button></div>':''}<div class="rf-zoom"><button data-map="out" aria-label="Zoom out">−</button><span>${Math.round(fm.zoom*100)}%</span><button data-map="in" aria-label="Zoom in">+</button><button data-map="fit">Fit</button></div><form class="rf-composer" id="rf-chat"><img class="map-composer-agent" src="assets/companion-blue-spirit.svg" alt="Knowledge companion"><input aria-label="Search tickets or cases" placeholder="Search tickets or cases…" value="${esc(fm.query)}"><button aria-label="Search cases">↑</button></form></section>${dialog()}</main>`};
function layout(){const stage=document.querySelector('.rf-stage');if(!stage)return;const fit=Math.min(stage.clientWidth/1659,stage.clientHeight/855);const overview=fm.fit||stage.clientWidth>=1000;const scale=overview?fit:Math.max(.8,fit);const focus=nodes.find(n=>n.kind==='root')||{x:829.5,y:427.5};stage.style.setProperty('--rf-scale',scale*fm.zoom);stage.style.setProperty('--rf-x',(fm.x+(overview?0:(829.5-focus.x)*scale*fm.zoom))+'px');stage.style.setProperty('--rf-y',(fm.y+(overview?0:(427.5-focus.y)*scale*fm.zoom))+'px')}
function findPosition(parent){const center=parent||{x:800,y:430};for(let radius=180;radius<1500;radius+=100){for(let i=0;i<16;i++){const angle=i*Math.PI/8;const x=Math.round(center.x+Math.cos(angle)*radius),y=Math.round(center.y+Math.sin(angle)*radius);if(x<100||x>1530||y<95||y>745)continue;if(nodes.every(n=>Math.hypot(n.x-x,n.y-y)>155))return {x,y}}}return {x:Math.min(1510,center.x+180),y:Math.min(740,center.y+180)}}
function closeDialog(){const id=fm.dialog?.id;fm.dialog=null;render();const target=[...document.querySelectorAll('[data-map="rename"],[data-map="add"]')].find(b=>b.dataset.id===id);target?.focus()}
bindKnowledge=function(){if(kb.view!=='map')return baseBind();layout();const stage=document.querySelector('.rf-stage');let drag=null;stage.onpointerdown=e=>{if(e.target.closest('button')||e.button!==0)return;drag={x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!drag)return;fm.x+=e.clientX-drag.x;fm.y+=e.clientY-drag.y;drag={x:e.clientX,y:e.clientY};layout()};stage.onpointerup=stage.onpointercancel=()=>drag=null;stage.onwheel=e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)fm.zoom=Math.max(.6,Math.min(2.5,fm.zoom*Math.exp(-e.deltaY*.008)));else{fm.x-=e.deltaX;fm.y-=e.deltaY}layout();document.querySelector('.rf-zoom span').textContent=Math.round(fm.zoom*100)+'%'};const form=document.querySelector('#rf-chat');form.onsubmit=e=>{e.preventDefault();fm.query=form.querySelector('input').value.trim();render();if(fm.query&&!nodes.some(matches))toast('No matching nodes.')};form.querySelector('input').oninput=e=>{if(!e.target.value&&fm.query){fm.query='';render();document.querySelector('#rf-chat input')?.focus()}};const editForm=document.querySelector('#map-node-form');if(editForm){document.querySelector('.rf-map').inert=true;document.querySelector('.workspace-rail').inert=true;document.querySelector('.mac-titlebar').inert=true;const input=editForm.querySelector('input');input.focus();input.select();editForm.onsubmit=e=>{e.preventDefault();const label=input.value.trim();if(!label){input.setCustomValidity('Enter a name.');input.reportValidity();return}const d=fm.dialog;const next=structuredClone(nodes);if(d.action==='rename'){const node=next.find(n=>n.id===d.id);if(node)node.label=label}else{const parent=nodes.find(n=>n.id===d.id);next.push({id:'folder-'+crypto.randomUUID(),label,parent:parent?.id||null,kind:'folder',...findPosition(parent)});if(parent)fm.expanded.add(parent.id)}if(save(next)){fm.undo=null;closeDialog()}};input.oninput=()=>input.setCustomValidity('')}};
window.addEventListener('resize',layout);
document.addEventListener('keydown',e=>{if(kb.view!=='map'||!fm.dialog||state.modal)return;if(e.key==='Escape'){e.preventDefault();closeDialog()}else if(e.key==='Tab'){const list=[...document.querySelectorAll('.map-dialog input,.map-dialog button')];const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-rf="home"]')){fm.query='';kb.view='map';kb.loading=false;state.screen='knowledge';history.replaceState(null,'','#knowledge');render();return}const b=e.target.closest('[data-map]');if(!b)return;const action=b.dataset.map,id=b.dataset.id,node=nodes.find(n=>n.id===id);if(action==='guide-close'){showMapGuide=false;render();return}if(action==='upload'){window.prepareMarketUpload();return}if(action==='edit'){fm.edit=!fm.edit;fm.query=''}else if(action==='toggle'){if(fm.edit)return;if(nodes.some(n=>n.parent===id)){fm.expanded.has(id)?fm.expanded.delete(id):fm.expanded.add(id)}else{toast('No notes yet. Use Edit to add one.');return}}else if(action==='add'||action==='rename'){fm.dialog={action,id}}else if(action==='cancel'){closeDialog();return}else if(action==='delete'&&node){const previous=structuredClone(nodes);const next=nodes.filter(n=>n.id!==id).map(n=>n.parent===id?{...n,parent:node.parent}:n);if(save(next))fm.undo=previous}else if(action==='undo'){if(fm.undo&&save(fm.undo))fm.undo=null}else if(action==='in')fm.zoom=Math.min(2.5,fm.zoom*1.2);else if(action==='out')fm.zoom=Math.max(.6,fm.zoom/1.2);else if(action==='fit'){fm.fit=true;fm.zoom=1;fm.x=0;fm.y=0}render()});
if(state.screen==='knowledge')render();
})();
